#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <openssl/evp.h>
#include <openssl/hmac.h>

#define MAX_PAYLOAD_SIZE 4096
#define HEADER_SIZE 16
#define HMAC_SIZE 32
#define MAX_CONNECTIONS 64
#define LISTEN_PORT 9443

// Protocol: [magic:4][version:2][type:2][length:4][reserved:4][payload:length][hmac:32]
// Types: 0x01=AUTH, 0x02=QUERY, 0x03=UPDATE, 0x04=BATCH

typedef struct {
    uint32_t magic;
    uint16_t version;
    uint16_t type;
    uint32_t length;   // payload length field
    uint32_t reserved;
} __attribute__((packed)) protocol_header_t;

typedef struct {
    char username[64];
    char session_token[128];
    int authenticated;
    int privilege_level;
} session_t;

typedef struct {
    uint16_t num_items;
    uint16_t item_size;
    uint32_t flags;
} __attribute__((packed)) batch_header_t;

static const uint8_t hmac_key[] = "protocol-hmac-key-v2-2024-secure";
static session_t sessions[MAX_CONNECTIONS];

// Verify HMAC-SHA256 signature of the message
int verify_message_hmac(const uint8_t *data, size_t data_len, const uint8_t *expected_hmac) {
    uint8_t computed[HMAC_SIZE];
    unsigned int hmac_len = HMAC_SIZE;

    // Check the return value of HMAC(): on failure it returns NULL and
    // 'computed' would hold uninitialized data. Fail closed in that case.
    if (HMAC(EVP_sha256(), hmac_key, sizeof(hmac_key) - 1,
             data, data_len, computed, &hmac_len) == NULL) {
        return 0;
    }
    if (hmac_len != HMAC_SIZE) {
        return 0;
    }

    // Constant-time comparison
    int result = 0;
    for (int i = 0; i < HMAC_SIZE; i++) {
        result |= computed[i] ^ expected_hmac[i];
    }
    return result == 0;
}

// Validate protocol header fields
int validate_header(const protocol_header_t *hdr) {
    if (hdr->magic != 0x50524F54) {  // "PROT"
        return -1;
    }
    if (hdr->version < 1 || hdr->version > 3) {
        return -1;
    }
    if (hdr->type < 0x01 || hdr->type > 0x04) {
        return -1;
    }
    return 0;
}

// Process batch operations - handles multiple sub-items in a single message
int process_batch(session_t *session, const uint8_t *payload, uint32_t payload_len) {
    if (!session->authenticated || session->privilege_level < 2) {
        fprintf(stderr, "Batch requires privilege level 2+\n");
        return -1;
    }

    if (payload_len < sizeof(batch_header_t)) {
        return -1;
    }

    const batch_header_t *batch = (const batch_header_t *)payload;

    // Calculate total size needed for batch items
    // Use uint32_t to prevent overflow
    uint32_t total_data_size = (uint32_t)batch->num_items * (uint32_t)batch->item_size;

    // Check for multiplication overflow
    if (batch->item_size != 0 && total_data_size / batch->item_size != batch->num_items) {
        fprintf(stderr, "Batch size overflow detected\n");
        return -1;
    }

    // Bounds check: ensure total data fits within payload
    uint32_t available = payload_len - (uint32_t)sizeof(batch_header_t);

    if (total_data_size > available) {
        fprintf(stderr, "Batch data exceeds payload bounds\n");
        return -1;
    }

    // Process each item
    const uint8_t *items_start = payload + sizeof(batch_header_t);
    char item_buffer[256];

    for (uint16_t i = 0; i < batch->num_items; i++) {
        uint32_t offset = (uint32_t)i * (uint32_t)batch->item_size;

        // Secondary bounds check
        if (offset + (uint32_t)batch->item_size > available) {
            break;
        }

        // Copy item for processing
        size_t copy_size = batch->item_size < sizeof(item_buffer) ? 
                          batch->item_size : sizeof(item_buffer) - 1;
        memcpy(item_buffer, items_start + offset, copy_size);
        item_buffer[copy_size] = '\0';

        printf("Processing batch item %d: %s\n", i, item_buffer);
    }

    return 0;
}

// Process query request
int process_query(session_t *session, const uint8_t *payload, uint32_t payload_len) {
    if (!session->authenticated) {
        return -1;
    }

    // Query payload is a null-terminated string
    if (payload_len == 0 || payload[payload_len - 1] != '\0') {
        return -1;
    }

    const char *query = (const char *)payload;
    printf("Query from %s: %s\n", session->username, query);
    return 0;
}

// Process authentication request
int process_auth(session_t *session, const uint8_t *payload, uint32_t payload_len) {
    if (payload_len < 64) {
        return -1;
    }

    // First 32 bytes: username, next 32 bytes: token
    memcpy(session->username, payload, 32);
    session->username[31] = '\0';
    memcpy(session->session_token, payload + 32, 32);
    session->session_token[31] = '\0';

    // Simple token validation (in production, verify against auth service)
    if (strlen(session->session_token) > 8) {
        session->authenticated = 1;
        session->privilege_level = 2;
    }

    return 0;
}

// Main message handler
int handle_message(int conn_idx, const uint8_t *buffer, size_t buffer_len) {
    if (buffer_len < HEADER_SIZE + HMAC_SIZE) {
        return -1;
    }

    const protocol_header_t *hdr = (const protocol_header_t *)buffer;

    if (validate_header(hdr) != 0) {
        return -1;
    }

    // Verify payload length field against actual received data
    // Check for overflow in addition
    if (hdr->length > MAX_PAYLOAD_SIZE) {
        fprintf(stderr, "Payload too large: %u\n", hdr->length);
        return -1;
    }

    size_t expected_total = HEADER_SIZE + (size_t)hdr->length + HMAC_SIZE;
    if (expected_total != buffer_len) {
        return -1;
    }

    // Verify HMAC over header + payload
    const uint8_t *hmac_ptr = buffer + HEADER_SIZE + hdr->length;
    if (!verify_message_hmac(buffer, HEADER_SIZE + hdr->length, hmac_ptr)) {
        fprintf(stderr, "HMAC verification failed\n");
        return -1;
    }

    const uint8_t *payload = buffer + HEADER_SIZE;
    uint32_t payload_len = hdr->length;

    session_t *session = &sessions[conn_idx];

    switch (hdr->type) {
        case 0x01:
            return process_auth(session, payload, payload_len);
        case 0x02:
            return process_query(session, payload, payload_len);
        case 0x03:
            printf("Update not implemented\n");
            return 0;
        case 0x04:
            return process_batch(session, payload, payload_len);
        default:
            return -1;
    }
}

int main(int argc, char *argv[]) {
    int server_fd, client_fd;
    struct sockaddr_in addr;
    uint8_t recv_buffer[8192];

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        return 1;
    }

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
    addr.sin_port = htons(LISTEN_PORT);

    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(server_fd);
        return 1;
    }

    listen(server_fd, 5);
    printf("Protocol server listening on port %d\n", LISTEN_PORT);

    int conn_count = 0;
    while ((client_fd = accept(server_fd, NULL, NULL)) >= 0) {
        ssize_t n = read(client_fd, recv_buffer, sizeof(recv_buffer));
        if (n > 0) {
            handle_message(conn_count % MAX_CONNECTIONS, recv_buffer, (size_t)n);
        }
        close(client_fd);
        conn_count++;
    }

    close(server_fd);
    return 0;
}
